<?php
namespace App\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;class AuthController extends Controller{function show(){return view('auth.login');}function login(Request $r){$c=$r->validate(['email'=>'required|email','password'=>'required']);if(!Auth::attempt($c,$r->boolean('remember')))return back()->withErrors(['email'=>'Invalid email or password.'])->onlyInput('email');$r->session()->regenerate();return redirect()->intended('/dashboard');}function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/login');}}
